ActionExecuteScript.Script:
using System;
using Triggernometry.FFXIV;
using Triggernometry.Expressions.String.Utils;
using Triggernometry.PluginBridges.BridgeNamazu.Modules;
using static Triggernometry.Expressions.String.Utils.DataStringHelper;

var m = new 魔光键影Module();
m.Scan();
m.RegisterAnnotatedMethods();

public class 魔光键影Module : ModuleBase
{
    public IntPtr EventFrameworkPtrPtr;
    public IntPtr GetInstanceDirectorFuncPtr;
    public IntPtr FireFuncPtr;

    public 魔光键影Module()
    {
        ScanMethod = () =>
        {
            EventFrameworkPtrPtr = Scanner.TryScan(
                "48 83 3D * * * * * 74 ? E8 ? ? ? ? " +
                "48 8B C8 E8 ? ? ? ? 3C",
                nameof(EventFrameworkPtrPtr));

            GetInstanceDirectorFuncPtr = Scanner.TryScan(
                "E8 * * * * 41 8B 5E 18 48 8B F8",
                nameof(GetInstanceDirectorFuncPtr));

            FireFuncPtr = Scanner.TryScan(
                "48 89 5C 24 ? 56 57 41 56 48 83 EC ? 48 8B 1D",
                nameof(FireFuncPtr));

            CheckIfAnyZeroPtr(
                EventFrameworkPtrPtr,
                GetInstanceDirectorFuncPtr,
                FireFuncPtr);
        };
    }

    [CallbackMethod("魔光键影")]
    public void CbFire(string command)
    {
        uint entityId = command.ParseData<HexOrDecId>();
        Fire(entityId);
    }

    public IntPtr GetInstanceDirectorPtr()
    {
        CheckIfAnyZeroPtr(EventFrameworkPtrPtr, GetInstanceDirectorFuncPtr);

        var framework = Memory.Read<IntPtr>(EventFrameworkPtrPtr);
        if (framework == IntPtr.Zero)
            return IntPtr.Zero;

        return Plugin.Call<IntPtr>(GetInstanceDirectorFuncPtr, framework);
    }

    public void Fire(uint targetId)
    {
        var target = Entity.GetEntityByID(targetId);
        if (target.Address != IntPtr.Zero)
            Fire(GetInstanceDirectorPtr(), target.Address, true);
        else
            Fire(GetInstanceDirectorPtr(), IntPtr.Zero, false);
    }

    private void Fire(IntPtr director, IntPtr targetPtr, bool success)
    {
        CheckBeforeExecution("魔光键影.Fire");
        CheckIfAnyZeroPtr(FireFuncPtr, director);
        var successArg = success ? (byte)1 : (byte)0;
        _ = Plugin.Call<byte>(FireFuncPtr, director, targetPtr, successArg);
    }
}

using System.Drawing;
using System.Windows.Forms;
using Triggernometry.UI.Forms;
using Triggernometry.Core.Actions;
using static Triggernometry.UI.Forms.GameConfigForm;


var info = new ConfigInfo("魔光键影宝宝椅", null, "阿洛", $"魔光键影_cfg");
ShowConfig(info, 魔光键影Entry.Setup);

public static class 魔光键影Entry
{
    static readonly Color Blue = Color.FromArgb(0x22, 0x66, 0xff);

    public static void Setup(GameConfigForm form)
    {
        OptionsTableLayoutPanel table = form.AddOptionGroup(" 致谢 ");
        form.AddLabel("　参考项目：", table);

        var link = form.AddLabel("　 · AtmoOmen/DailyRoutines", table);
        link.ForeColor = Blue;
        link.Cursor = Cursors.Hand;
        link.Click += async(_, __) => await new ActionLaunchProcess { Path = "https://github.com/Dalamud-DailyRoutines/" }.ExecuteAsync();

        link = form.AddLabel("　 · geedama/moguang-typing", table);
        link.ForeColor = Blue;
        link.Cursor = Cursors.Hand;
        link.Click += async (_, __) => await new ActionLaunchProcess { Path = "https://github.com/geedama/moguang-typing" }.ExecuteAsync();

        form.AddLabel("　如需更方便地使用此功能，请下载安装 Daily Routines。", table);

        table = form.AddOptionGroup(" 选项 ");
        var autoFire = new OptionChk("　全自动开火", "bFire", true);
        var minTime  = new OptionNud("　 · 最短间隔 / 秒", "tMin", 1.00m, 0.01m, 5m, 2, 0.01m);
        var maxTime  = new OptionNud("　 · 最长间隔 / 秒", "tMax", 2.00m, 0.01m, 10m, 2, 0.01m);
        var copy     = new OptionChk("　将词汇复制至剪贴板", "bCopy", false);

        form.AddOptions(table, autoFire, minTime, maxTime, copy);

        autoFire.Chk.CheckedChanged += (s, e) => Toggle();
        Toggle();

        void Toggle()
        {
            minTime.Visible = autoFire.Chk.Checked;
            maxTime.Visible = autoFire.Chk.Checked;
        }

        table = form.AddOptionGroup(" 说明 ");
        form.AddLabel("　 · 在键斗广场输入 /e cfg 可开启此界面。", table).ForeColor = Blue;
        form.AddLabel("　 · 全自动模式需要鲶鱼精邮差，否则仅能使用剪贴板模式（但可能无法粘贴）。", table);
        form.AddLabel("　 · 设置临时标量变量 debug = 1 可开启调试模式。", table);


        form.MinimumSize = new Size(600, 300);
    }
}
